package com.bn.aliagent.insight.aggregate; import java.time.*; import java.util.*;
public final class DailyFinalizationService { private final AggregationStore store; public DailyFinalizationService(AggregationStore store){this.store=store;} public AggregateRevision finalizeDay(String tenant,String metric,int version,LocalDate day,ZoneId zone,Map<String,String> dimensions){var sorted=new TreeMap<>(dimensions);var hours=store.hourly(tenant,metric,version,day,zone,sorted);long n=hours.stream().mapToLong(AggregateRevision::numerator).sum(),d=hours.stream().mapToLong(AggregateRevision::denominator).sum();var key=new AggregateKey(tenant,metric,version,WindowGranularity.DAILY,day.atStartOfDay(zone).toInstant(),sorted);int previous=store.latest(key).map(AggregateRevision::revision).orElse(0);return store.append(AggregateRevision.next(key,previous+1,n,d),previous);}}
